export function visitExpression(root,visitor){
 const jobs=[{node:root,ready:false}],values=[];
 while(jobs.length){const {node,ready}=jobs.pop();if(node.type==='literal'){values.push(visitor.literal(node.value));continue;}if(!ready){jobs.push({node,ready:true},{node:node.right,ready:false},{node:node.left,ready:false});}else{const right=values.pop(),left=values.pop();values.push(visitor.binary(node.op,left,right));}}
 return values[0];
}

